CREATE OR REPLACE FUNCTION public.conc_boleto_verified_invoices(p_ids uuid[]) RETURNS TABLE(ar_id uuid,hotel_id text,credit_date date) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT DISTINCT a.id,a.hotel_id,b.line_date FROM public.ar_to_invoice_entries a JOIN public.conc_francesinha_entries f ON f.matched_ar_id=a.id AND f.hotel_id=a.hotel_id AND f.acao='liquidacao' JOIN public.conc_bank_entries b ON b.id=f.matched_bank_id AND b.hotel_id=a.hotel_id AND b.amount>0 AND b.matched_at IS NOT NULL WHERE a.id=ANY(p_ids) AND auth.uid() IS NOT NULL AND public.can_view_hotel_data(auth.uid(),a.hotel_id) AND NOT public.has_role(auth.uid(),'ri') AND (public.is_ar_manager(auth.uid()) OR public.can_justify_conciliacao(auth.uid(),a.hotel_id)) $$;
REVOKE ALL ON FUNCTION public.conc_boleto_verified_invoices(uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.conc_boleto_verified_invoices(uuid[]) TO authenticated,service_role;